{
  "title": "CSCI-264: Honors Analysis of Algorithms - Foundations Lesson Blueprint",
  "learningObjectives": [
    "Define and apply asymptotic notation to accurately describe the growth rate of algorithmic resource usage relative to input size.",
    "Construct and verify a loop invariant to formally prove the correctness of iterative algorithms through initialization, maintenance, and termination.",
    "Represent and traverse graph structures using adjacency matrices or adjacency lists to solve reachability and path-finding problems."
  ],
  "beats": [
    {
      "title": "Introduction to Algorithmic Analysis",
      "claim": "Algorithm analysis connects a precise problem specification to a correctness argument and resource bounds.",
      "example": "When designing a search routine, the specification must explicitly state the input data, the expected output, and the maximum allowed time or memory usage.",
      "visualDirection": "Display a split-screen graphic: left side shows a problem statement box, right side shows a graph plotting time vs. input size, with a connecting arrow labeled 'Analysis Bridge'.",
      "sourceIds": ["mit-algorithms"]
    },
    {
      "title": "Asymptotic Notation Basics",
      "claim": "Asymptotic notation describes how resource use grows with input size.",
      "example": "An algorithm that processes each element once and performs a constant number of operations per element grows linearly, expressed as O(n).",
      "visualDirection": "Show a line graph with three curves labeled O(1), O(n), and O(n^2), highlighting the steepness difference as n increases.",
      "sourceIds": ["mit-algorithms"]
    },
    {
      "title": "Loop Invariants for Correctness",
      "claim": "A loop invariant supports a proof by initialization, maintenance, and termination.",
      "example": "In a sum-accumulation loop, the invariant 'sum equals the total of all processed elements' holds before the loop, remains true after each iteration, and guarantees the final result matches the total sum.",
      "visualDirection": "Animate a loop counter and a running total variable, with checkmarks appearing at 'Initialization', 'Maintenance', and 'Termination' stages.",
      "sourceIds": ["mit-algorithms"]
    },
    {

      "title": "Divide-and-Conquer Strategy",
      "claim": "Divide-and-conquer algorithms split a problem, solve subproblems, and combine their results.",
      "example": "Merge sort divides an array into halves, recursively sorts each half, and merges the sorted halves back together.",
      "visualDirection": "Illustrate a binary tree where the root is the full array, children are halves, and leaves are single elements, with arrows showing the divide and combine phases.",
      "sourceIds": ["mit-algorithms"]
    },
    {
      "title": "Recurrence Relations",
      "claim": "Recurrences describe the cost of recursive algorithms.",
      "example": "The merge sort recurrence T(n) = 2T(n/2) + O(n) captures the cost of splitting, solving two subproblems, and merging.",
      "visualDirection": "Display a mathematical equation box with T(n) = 2T(n/2) + cn, alongside a small tree diagram showing two recursive calls branching from one node.",
      "sourceIds": ["mit-algorithms"]
    },
    {
      "title": "Graph Representation",
      "claim": "Graphs can be represented with adjacency structures for traversal and path algorithms.",
      "example": "An adjacency matrix uses a 2D array where entry (i,j) indicates an edge between vertex i and vertex j, enabling direct edge lookup.",
      "visualDirection": "Show a 4x4 grid with 1s marking edges between nodes, labeled 'Adjacency Matrix', next to a list of node pairs labeled 'Edge List'.",
      "sourceIds": ["opendsa"]
    },
    {
      "title": "Data Structure Invariants",
      "claim": "Representation choices and invariants determine which operations are efficient and which errors are possible.",
      "example": "A stack invariant requires that the top element is always the most recently added item, ensuring O(1) push and pop operations but preventing random access.",
      "visualDirection": "Draw a vertical stack with a 'top' pointer, showing push adding to the top and pop removing from the top, with a lock icon indicating no middle access.",
      "sourceIds": ["opendsa"]
    },
    {
      "title": "Sorting and Hashing Foundations",
      "claim": "Core methods include sorting, hashing, trees, graphs, shortest paths, and dynamic programming.",
      "example": "Hash tables map keys to locations using a hash function, requiring a collision strategy like chaining or open addressing to maintain data integrity.",
      "visualDirection": "Show a hash table with buckets, a key being hashed to a bucket index, and a collision chain resolving via linked lists.",
      "sourceIds": ["opendsa"]
    },
    {
      "title": "Dynamic Programming Overview",
      "claim": "Dynamic programming records solutions to overlapping subproblems.",
      "example": "The Fibonacci sequence calculation stores previously computed values in a table to avoid redundant recursive calls, reducing time complexity from exponential to linear.",
      "visualDirection": "Display a table filling row by row with Fibonacci numbers, highlighting how each cell references two prior cells.",
      "sourceIds": ["mit-algorithms"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "A disciplined solution states inputs and outputs, proves correctness, and then analyzes time and space.",
      "example": "Before coding, students must document the input format, output format, correctness proof using invariants or induction, and derive the time/space complexity using asymptotic notation.",
      "visualDirection": "Show a checklist graphic with four boxes: 'Specify I/O', 'Prove Correctness', 'Derive Complexity', 'Verify Invariants', with a green checkmark appearing sequentially.",
      "sourceIds": ["rit-csci-264", "mit-algorithms"]
    }
  ]
}
